"""RPN calculator VM.

Evaluates reverse Polish notation expressions supporting:
  +   - addition
  -   - subtraction
  *   - multiplication
  /   - division
  neg - unary negation
  dup - duplicate top of stack
  swap- swap top two stack values
"""


class RPNError(Exception):
    """Base class for all RPN evaluation errors."""


class StackUnderflow(RPNError):
    pass


class LeftoverStack(RPNError):
    pass


class UnknownToken(RPNError):
    pass


class DivisionByZero(RPNError):
    pass


def eval_rpn(tokens: list[str]) -> float:
    stack: list[float] = []

    def pop(n: int, op: str) -> list[float]:
        if len(stack) < n:
            raise StackUnderflow(
                f"operator '{op}' requires {n} operand(s), "
                f"but only {len(stack)} available on the stack"
            )
        vals = stack[-n:] if n else []
        del stack[len(stack) - n:]
        return vals

    for tok in tokens:
        if tok in ("+", "-", "*", "/"):
            a, b = pop(2, tok)
            if tok == "+":
                stack.append(a + b)
            elif tok == "-":
                stack.append(a - b)
            elif tok == "*":
                stack.append(a * b)
            else:
                if b == 0:
                    raise DivisionByZero(f"division by zero: {a} / 0")
                stack.append(a / b)
        elif tok == "neg":
            (a,) = pop(1, "neg")
            stack.append(-a)
        elif tok == "dup":
            (a,) = pop(1, "dup")
            stack.extend([a, a])
        elif tok == "swap":
            a, b = pop(2, "swap")
            stack.extend([b, a])
        else:
            try:
                stack.append(float(tok))
            except ValueError:
                raise UnknownToken(f"unknown token: '{tok}'") from None

    if len(stack) != 1:
        leftover = ", ".join(repr(v) for v in stack)
        raise LeftoverStack(
            f"expression left {len(stack)} values on the stack "
            f"(expected exactly 1): {leftover}"
        )
    return stack[0]


def main() -> None:
    import sys

    for line in sys.stdin:
        tokens = line.split()
        if not tokens:
            continue
        try:
            print(eval_rpn(tokens))
        except RPNError as exc:
            print(f"error: {exc}", file=sys.stderr)


if __name__ == "__main__":
    main()

